operations.text:
_EmissionStrength ("Emission Strength", Float) = 1.0

// Reflection probe response. 1.0 is the stock Standard result.
_ReflectionStrength ("Reflection Strength", Range(0,2)) = 1.0

// VRC Light Volumes: replaces flat light-probe ambient with the world's
// baked light volumes so the accessory lights the same as the avatar.
[ToggleUI] _UseLightVolumes ("VRC Light Volumes", Float) = 1.0
_LightVolumeIntensity ("Light Volume Intensity", Range(0,2)) = 1.0
_LightVolumeSpecular ("Light Volume Specular", Range(0,2)) = 1.0

// Custom StandardSpecular-based lighting model that folds in VRC Light Volumes.
// Forward only (VRChat is forward); target 5.0 is required by the Light Volumes cginc
// (Texture3D / Texture2DArray.SampleLevel).
#pragma surface surf StandardSpecularLV fullforwardshadows alpha:fade exclude_path:deferred exclude_path:prepass

#pragma target 5.0

#include "UnityPBSLighting.cginc"

// The surface-shader analysis parser is a cut-down HLSL parser and cannot handle the
// modern syntax inside the Light Volumes cginc (const params, etc.). Feed it lightweight
// stubs during analysis; the real per-platform compile (analysis undefined) pulls in the
// actual implementation.
#ifdef SHADER_TARGET_SURFACE_ANALYSIS
    float LightVolumesEnabled() { return 0; }
    void LightVolumeSH(float3 worldPos, out float3 L0, out float3 L1r, out float3 L1g, out float3 L1b, float3 worldPosOffset, float3 worldNormal) { L0 = 0; L1r = 0; L1g = 0; L1b = 0; }
    float3 LightVolumeEvaluate(float3 worldNormal, float3 L0, float3 L1r, float3 L1g, float3 L1b) { return 0; }
    float3 LightVolumeSpecular(float3 f0, float smoothness, float3 worldNormal, float3 viewDir, float3 L0, float3 L1r, float3 L1g, float3 L1b) { return 0; }
#else
    #include "{{LIGHT_VOLUMES_INCLUDE}}"
#endif

// _Emission is an [HDR] Color. Held in a fixed4 it clamps at 2.0 wherever fixed is a
// real 11-bit type (Android/Quest), silently capping HDR emission on those platforms.
float4 _Emission;
half _EmissionStrength;

// Per-fragment carrier for the Light Volume specular. _GI runs before the lighting
// function in the same fragment, so it computes the value and the lighting function
// adds it after the standard BRDF (keeps it out of the reflection-probe fresnel term).
static half3 g_ZawooLVSpec = 0;

// Standard specular lighting, plus the Light Volume soft-spec on top.
inline half4 LightingStandardSpecularLV (SurfaceOutputStandardSpecular s, half3 viewDir, UnityGI gi)
{
    half4 c = LightingStandardSpecular(s, viewDir, gi);
    c.rgb += g_ZawooLVSpec;
    return c;
}

inline void LightingStandardSpecularLV_GI (inout SurfaceOutputStandardSpecular s, UnityGIInput data, inout UnityGI gi)
{
    // Standard reflection-probe specular, atmospheric fog, direct light, etc.
    LightingStandardSpecular_GI(s, data, gi);

    g_ZawooLVSpec = 0;

    // Light Volumes are ambient, so only touch the forward base pass.
#if defined(UNITY_PASS_FORWARDBASE)
    if (_UseLightVolumes > 0.5 && LightVolumesEnabled() > 0.5)
    {
        // s.Normal is already world-space inside the lighting function.
        float3 L0, L1r, L1g, L1b;
        LightVolumeSH(data.worldPos, L0, L1r, L1g, L1b, float3(0,0,0), s.Normal);

        // Blend towards the volumetric ambient instead of overwriting the probe ambient,
        // so intensity 0 falls back to light probes rather than going black.
        float3 lvDiffuse = max(0.0, LightVolumeEvaluate(s.Normal, L0, L1r, L1g, L1b));
        gi.indirect.diffuse = lerp(gi.indirect.diffuse, lvDiffuse * _LightVolumeIntensity, saturate(_LightVolumeIntensity));

        // Soft SH specular from the same volumes (uses the specular colour as f0).
        float3 viewDir = normalize(data.worldViewDir);
        g_ZawooLVSpec = max(0.0, LightVolumeSpecular(s.Specular, s.Smoothness, s.Normal, viewDir, L0, L1r, L1g, L1b)) * (_LightVolumeIntensity * _LightVolumeSpecular);
    }
#endif

    gi.indirect.specular *= _ReflectionStrength;
}
